pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor (address) and a candidate futureUnlock (uint256)
    // We require the actor to be non-zero and the futureUnlock to be strictly in the future
    // (beyond current block.timestamp) so that the reference sets unlockTime to that future value,
    // while the mutant that forces block.timestamp will not.
    function testFuzz_property(address actor, uint256 futureUnlock, uint256 pay) public {
        vm.assume(actor != address(0));
        // keep pay reasonable but allow >0 so Put executes state change
        pay = bound(pay, 1 wei, 10 ether);
        // ensure futureUnlock is strictly greater than current block.timestamp
        vm.assume(futureUnlock > block.timestamp);

        // fund the actor and call Put as that actor
        vm.deal(actor, pay);
        vm.prank(actor);
        c.Put{value: pay}(futureUnlock);

        // The reference contract stores unlockTime = max(_unlockTime, block.timestamp).
        // Since we required futureUnlock > block.timestamp, the reference will store futureUnlock.
        // The mutant that always writes block.timestamp will store a strictly smaller value.
        // Assert that the stored unlockTime for actor is equal to futureUnlock.
        (uint storedUnlock,,) = getHolder(actor);
        assertTrue(storedUnlock == futureUnlock);
    }

    // helper to read the public mapping components via the autogenerated getter
    function getHolder(address a) internal returns (uint unlockTime, uint balance, bool dummy) {
        // The reference contract declares: mapping (address => Holder) public Acc;
        // The compiler generates Acc(address) returning (uint unlockTime, uint balance).
        // We call it and return with a dummy third value to allow tuple assignment above.
        (uint u, uint b) = c.Acc(a);
        return (u, b, true);
    }
}

