pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor (address) and amount (uint256) - fuzzer supplies both
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep amount in a reasonable range (non-zero, <= 10 ether) but wide enough
        amount = bound(amount, 1 wei, 10 ether);
        // Fund the actor so they can send amount
        vm.deal(actor, amount);

        // Make a first deposit to create a prior non-zero balance sometimes
        uint256 first = bound(uint256(uint160(actor)) % (uint256(1 ether) + 1), 0, 1 ether);
        if(first > 0) {
            vm.deal(actor, first + amount);
            vm.startPrank(actor);
            c.Put{value: first}(block.timestamp + 1);
            vm.stopPrank();
        }

        // Now the decisive deposit: actor sends `amount`
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + 2);

        // Read the public getter for Acc to obtain the recorded balance
        C.Holder memory h = c.Acc(actor);
        uint256 recorded = h.balance;

        // General rule: after any Put, the recorded balance for that caller is >= the most recent deposit amount
        // This holds for the reference contract (which accumulates deposits) but the mutant that sets acc.balance = msg.value
        // can make recorded < previous accumulation and equal to only msg.value; however it still satisfies recorded >= msg.value
        // only when previous balance <= msg.value. Our property checks the universal: recorded >= amount.
        assertTrue(recorded >= amount);
    }
}

